Q: How to unit test SQL Server User-Defined Table Types against C# classes to ensure property order and compatibility? A: <p>I'm using EF Core for managing my database schema. Which doesn't have any support for UDTT. So I built my own.</p>
<p>I define each UDTT based on an EF Core keyless entity type with an added <code>[SqlType]</code> attribute.</p>
<pre class="lang-cs prettyprint-override"><code>[AttributeUsage(AttributeTargets.Class, AllowMultiple = false)]
public class SqlTypeAttribute : Attribute
{
    public string Name { get; set; }
}

[SqlType(Name = &quot;[UDDT name]&quot;)]
public class MyClass
{
    // ...
}
</code></pre>
<p>By extending <code>SqlServerMigrationsSqlGenerator</code>, I can reuse its support for generating the sql for column definitions;</p>
<pre class="lang-cs prettyprint-override"><code>// loosely based on https://github.com/dotnet/efcore/blob/d4aa1ea4946313f59b643d632657ef4e895d96e6/src/EFCore.Relational/Migrations/MigrationsSqlGenerator.cs#L510
// might want to implement something based on https://stackoverflow.com/a/53592559/4139809 ?
public class SqlServerTypeSqlGenerator : SqlServerMigrationsSqlGenerator
{
    public SqlServerTypeSqlGenerator(MigrationsSqlGeneratorDependencies dependencies, ICommandBatchPreparer commandBatchPreparer) : base(dependencies, commandBatchPreparer)
    {
    }

    public void GenerateDropUdt(
        string name,
        string schema, 
        MigrationCommandListBuilder builder)
    {
        builder
            .Append(&quot;IF TYPE_ID(N'&quot;)
            .Append(Dependencies.SqlGenerationHelper.DelimitIdentifier(name, schema))
            .AppendLine(&quot;') IS NOT NULL&quot;);

        using (builder.Indent())
        {
            builder
                .Append(&quot;DROP TYPE &quot;)
                .Append(Dependencies.SqlGenerationHelper.DelimitIdentifier(name, schema))
                .AppendLine();
        }
        builder.AppendLine(Dependencies.SqlGenerationHelper.StatementTerminator);
        EndStatement(builder);
    }

    public void GenerateCreateUdt(
        string name,
        string schema,
        IEnumerable&lt;IColumnBase&gt; columns,
        IModel model,
        MigrationCommandListBuilder builder)
    {
        GenerateDropUdt(name, schema, builder);

        builder
            .Append(&quot;CREATE TYPE &quot;)
            .Append(Dependencies.SqlGenerationHelper.DelimitIdentifier(name, schema))
            .AppendLine(&quot; AS TABLE (&quot;);

        using (builder.Indent())
        {
            var operation = new CreateTableOperation();
            operation.Columns.AddRange(columns.Select(c =&gt; new AddColumnOperation() {
                Name = c.Name,
                ColumnType = c.StoreType,
                IsRowVersion = false,
                IsNullable = true
            }));
            CreateTableColumns(operation, model, builder);
            builder.AppendLine();
        }

        builder.Append(&quot;)&quot;);
        builder.AppendLine(Dependencies.SqlGenerationHelper.StatementTerminator);
        EndStatement(builder);
    }

    public IReadOnlyList&lt;MigrationCommand&gt; GenerateCreateUdt(
        IModel model, 
        IRelationalModel relationalModel,
        MigrationsSqlGenerationOptions options = MigrationsSqlGenerationOptions.Default)
    {
        Options = options;
        var builder = new MigrationCommandListBuilder(Dependencies);
        foreach (var type in relationalModel.Tables)
        {
            var attrib = type.EntityTypeMappings
                .Select(e =&gt; e.TypeBase.ContainingEntityType.ClrType.GetCustomAttribute&lt;SqlTypeAttribute&gt;())
                .FirstOrDefault(a =&gt; a != null);
            if (attrib == null)
                continue;

            GenerateCreateUdt(attrib.Name ?? type.Name, type.Schema, type.Columns, model, builder);
        }
        foreach (var type in relationalModel.Views)
        {
            var attrib = type.EntityTypeMappings
                .Select(e =&gt; e.TypeBase.ContainingEntityType.ClrType.GetCustomAttribute&lt;SqlTypeAttribute&gt;())
                .FirstOrDefault(a =&gt; a != null);
            if (attrib == null)
                continue;

            GenerateCreateUdt(attrib.Name ?? type.Name, type.Schema, type.Columns, model, builder);
        }
        return builder.GetCommandList();
    }
}
</code></pre>
<p>Replace the service;</p>
<pre class="lang-cs prettyprint-override"><code>.UseSqlServer(...)
.ReplaceService&lt;IMigrationsSqlGenerator, SqlServerTypeSqlGenerator&gt;()
</code></pre>
<p>Then after applying migrations, calling <code>GenerateCreateUdt</code> will give you a list of migration commands to [re]create each UDTT type. Which you can either turn into an sql script, or execute immediately.</p>
<pre class="lang-cs prettyprint-override"><code>var model = dbContext.Model;
var relational = model.GetRelationalModel();

var generator = (SqlServerTypeSqlGenerator)dbContext.GetService&lt;IMigrationsSqlGenerator&gt;();
var commandExecutor = dbContext.GetService&lt;IMigrationCommandExecutor&gt;();
var connection = dbContext.GetService&lt;IRelationalConnection&gt;();

var commands = generator.GenerateCreateUdt(model, relational );

await commandExecutor.ExecuteNonQueryAsync(commands, connection, default);
</code></pre>

Q: Get only related items in Laravel A: <p>Pluck only relation (Best &amp; clean)</p>
<pre><code>public function getBookCover() {
    $bookCover = Book::with('getBook')-&gt;get()-&gt;pluck('getBook');
    return response()-&gt;json($bookCover);
}
</code></pre>

Q: Poetry: how to deal with hardware dependant libraries A: <p>As <a href="https://python-poetry.org/docs/dependency-specification/#exclusive-extras" rel="nofollow noreferrer">the official guideline</a>, you should define your <code>pyproject.toml</code> as below:</p>
<pre><code>[project]
name = &quot;torch-example&quot;
requires-python = &quot;&gt;=3.10&quot;

[project.optional-dependencies]
cpu = [
    &quot;torch (==2.3.1+cpu)&quot;,
]
cuda = [
    &quot;torch (==2.3.1+cu118)&quot;,
]

[tool.poetry]
package-mode = false

[tool.poetry.dependencies]
torch = [
    { markers = &quot;extra == 'cpu' and extra != 'cuda'&quot;, source = &quot;pytorch-cpu&quot;},
    { markers = &quot;extra == 'cuda' and extra != 'cpu'&quot;, source = &quot;pytorch-cuda&quot;},
 ]

[[tool.poetry.source]]
name = &quot;pytorch-cpu&quot;
url = &quot;https://download.pytorch.org/whl/cpu&quot;
priority = &quot;explicit&quot;

[[tool.poetry.source]]
name = &quot;pytorch-cuda&quot;
url = &quot;https://download.pytorch.org/whl/cu118&quot;
priority = &quot;explicit&quot;
</code></pre>
<p>Keep in mind that all combinations of possible extras available in your project need to be compatible with each other. This means that in order to use differing or incompatible versions across different combinations, you need to make your extra markers <em>exclusive</em>. For example, the following installs PyTorch from one source repository with CPU versions when the <strong><code>cuda</code></strong> extra is <em>not</em> specified, while the other installs from another repository with a separate version set for GPUs when the <strong><code>cuda</code></strong> extra <em>is</em> specified.</p>
